import{_ as t,o as e,c as i,a1 as o}from"./chunks/framework.BxsNGn3-.js";const I=JSON.parse('{"title":"关于AI","description":"","frontmatter":{"title":"关于AI"},"headers":[],"relativePath":"guide/about-ai.md","filePath":"guide/about-ai.md"}'),l={name:"guide/about-ai.md"};function r(n,a,s,u,A,c){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="ai时代下计算机专业的现状与未来" tabindex="-1">AI时代下计算机专业的现状与未来 <a class="header-anchor" href="#ai时代下计算机专业的现状与未来" aria-label="Permalink to &quot;AI时代下计算机专业的现状与未来&quot;">​</a></h1><blockquote><p>核心想法：不恐惧AI、不依赖AI，先打好根基，再善用AI。</p></blockquote><ul><li>💻 行业门槛：计算机行业门槛正在持续抬高，高薪岗位两条主线——<strong>要么有扎实学历背书，要么有硬核落地能力</strong>，二者至少占其一。</li><li>📊 就业现实：计算机专业就业率并没有大家想象中那么高。根源在于高校课程体系更新慢，很多同学缺少主动自学、持续跟进技术的习惯。</li><li>🤖 如何看待AI：AI能力很强，但远没有到可以替代一切的程度。不要逃避，学会拥抱它，把AI当成一套工具、一个技术助手。 <blockquote><p>前提：四大件、算法刷题、项目实践这些基础功课一点不能偷懒。 经历过“古法编程”，亲手踩过坑，你才有能力看懂AI输出、审核AI代码、掌控AI。</p></blockquote></li><li>🛠️ 程序员的核心：从来不是掌握某一门编程语言、某一个热门框架。<strong>真正的核心竞争力是工程能力</strong>。</li></ul><h3 id="学习准则" tabindex="-1">学习准则 <a class="header-anchor" href="#学习准则" aria-label="Permalink to &quot;学习准则&quot;">​</a></h3><ol><li>基础优先：先吃透计算机底层基础，基础是驾驭AI的底气</li><li>AI定位：AI是辅助工具，不是替我写代码的替身</li><li>持续输出：多写项目、多复盘，把学到的东西落地</li><li>长期心态：技术更新很快，保持自学习惯比追逐热点更重要</li></ol><h3 id="误区避雷" tabindex="-1">误区避雷 <a class="header-anchor" href="#误区避雷" aria-label="Permalink to &quot;误区避雷&quot;">​</a></h3><p>❌ 误区1：有AI就不用学基础、不用刷题 ❌ 误区2：跟风追各种AI热点，底层一片空白 ❌ 误区3：完全抵触AI，拒绝使用工具提升效率</p><p>✅ 正确路线：基础打底 → 独立思考 → 用AI提速、查错、拓展思路</p>',8)])])}const _=t(l,[["render",r]]);export{I as __pageData,_ as default};
